                <th className="px-4 py-5 text-center text-[14px] font-black uppercase text-slate-400">GST Status</th>
                <th className="px-4 py-5 text-center text-[14px] font-black uppercase text-slate-400">Status</th>
                <th className="px-4 py-5 text-[14px] font-black uppercase text-slate-400 text-right w-[100px]">Actions</th>
