import React, { useState, useEffect, useMemo, useCallback } from 'react';
import GstMasterPortfolio from './GstMasterPortfolio';
import GSTClientFormModal from '../Clientform/GSTClientFormModal';
import { mockBackend } from '../../services/mockBackend';
import { Client, JurisdictionType, ClientStatus, GstStatus, GstRegType, GstFilingFreq, ConstitutionType } from '../../types';

const CSV_HEADERS = [
  "Legal Name", "Trade Name", "Mobile", "Email", "Client Status",
  "GSTIN", "Portal Username", "Portal Password", "GST Status", 
  "Reg Date", "Cancel Date", "Reg Type", "Filing Freq", 
  "Constitution", "Jurisdiction", "Sector", "Range", 
  "Address", "Bank Name", "Account No", "IFSC", "Remarks"
];

const GSTPortfolio: React.FC = () => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [refreshTrigger, setRefreshTrigger] = useState(0);
  const [search, setSearch] = useState('');
  const [jurisdictionFilter, setJurisdictionFilter] = useState<JurisdictionType | 'All'>('All');
  const [sectorFilter, setSectorFilter] = useState<string>('All');
  const [rangeFilter, setRangeFilter] = useState<string>('All');
  const [showDataOptions, setShowDataOptions] = useState(false);
  const [clients, setClients] = useState<Client[]>([]);

  const refreshData = useCallback(async () => {
    const data = await mockBackend.getClients();
    setClients(data.filter(c => !!c.gstProfile));
    setRefreshTrigger(p => p + 1);
  }, []);

  useEffect(() => {
    refreshData();
  }, []);

  const stats = useMemo(() => {
    const total = clients.length;
    const active = clients.filter(c => c.status === 'Active Filing').length;
    const caseStudy = clients.filter(c => c.status === 'Case-by-Case').length;
    const inactive = clients.filter(c => c.status.startsWith('Inactive')).length;
    return { total, active, caseStudy, inactive };
  }, [clients]);

  const sectors = useMemo(() => {
    const s = new Set<string>();
    clients.forEach(c => {
      if (c.gstProfile?.jurisdictionType === 'State' && c.gstProfile.sector) {
        s.add(c.gstProfile.sector);
      }
    });
    return Array.from(s).sort();
  }, [clients]);

  const ranges = useMemo(() => {
    const r = new Set<string>();
    clients.forEach(c => {
      if (c.gstProfile?.jurisdictionType === 'Center' && c.gstProfile.range) {
        r.add(c.gstProfile.range);
      }
    });
    return Array.from(r).sort();
  }, [clients]);

  const handleJurisdictionChange = (val: string) => {
    setJurisdictionFilter(val as any);
    setSectorFilter('All');
    setRangeFilter('All');
  };

  const handleExportCSV = () => {
    const rows = clients.map(c => [
      c.legalName, c.tradeName, c.mobile, c.email || "", c.status, c.gstProfile?.gstin,
      c.gstProfile?.username, c.gstProfile?.password || "", c.gstProfile?.gstStatus,
      c.gstProfile?.regDate, c.gstProfile?.cancelDate || "", c.gstProfile?.regType,
      c.gstProfile?.filingFreq, c.gstProfile?.constitution, c.gstProfile?.jurisdictionType,
      c.gstProfile?.sector || "", c.gstProfile?.range || "", `"${(c.gstProfile?.address || "").replace(/"/g, '""')}"`,
      c.bankDetails?.bankName || "", c.bankDetails?.accountNo || "", c.bankDetails?.ifsc || "", `"${(c.remarks || "").replace(/"/g, '""')}"`
    ]);
    const csvContent = [CSV_HEADERS, ...rows].map(e => e.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `GST_Portfolio_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
    setShowDataOptions(false);
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async (e) => {
      const text = e.target?.result as string;
      const rows = text.split('\n').slice(1);
      const allClients = await mockBackend.getClients();
      for (const row of rows) {
        if (!row.trim()) continue;
        const cols = row.split(',').map(c => c.trim().replace(/^"|"$/g, ''));
        const gstin = cols[5];
        if (!gstin) continue;
        const existing = allClients.find(c => c.gstProfile?.gstin === gstin);
        try {
          await mockBackend.saveClient({
            id: existing?.id, legalName: cols[0], tradeName: cols[1], mobile: cols[2], email: cols[3],
            status: (cols[4] as ClientStatus) || 'Active Filing',
            gstProfile: {
              gstin, username: cols[6] || '', password: cols[7] || '',
              gstStatus: (cols[8] as GstStatus) || 'Active', regDate: cols[9] || new Date().toISOString().split('T')[0],
              regType: (cols[11] as GstRegType) || 'Regular', filingFreq: (cols[12] as GstFilingFreq) || 'Monthly',
              constitution: (cols[13] as ConstitutionType) || 'Proprietorship', jurisdictionType: (cols[14] as JurisdictionType) || 'State',
              sector: cols[15], range: cols[16], address: cols[17], stakeholders: existing?.gstProfile?.stakeholders || []
            },
            bankDetails: { bankName: cols[18] || '', accountNo: cols[19] || '', ifsc: cols[20] || '' },
            remarks: cols[21]
          });
        } catch (err) {}
      }
      refreshData();
      setShowDataOptions(false);
    };
    reader.readAsText(file);
    event.target.value = ''; 
  };

  return (
    <div className="flex flex-col h-full space-y-3 pb-4 overflow-hidden">
      <div className="flex flex-col lg:flex-row items-center gap-3 bg-white p-2.5 rounded-[1.5rem] border border-slate-200 shadow-sm shrink-0">
        <div className="flex items-center gap-4 px-2 border-r border-slate-100 hidden md:flex shrink-0">
          <div className="flex flex-col items-center min-w-[32px]"><span className="text-[9px] font-black text-slate-400 uppercase mb-1">Total</span><span className="text-lg font-black text-slate-900">{stats.total}</span></div>
          <div className="flex flex-col items-center min-w-[32px]"><span className="text-[9px] font-black text-green-500 uppercase mb-1">Active</span><span className="text-lg font-black text-green-600">{stats.active}</span></div>
          <div className="flex flex-col items-center min-w-[32px]"><span className="text-[9px] font-black text-amber-500 uppercase mb-1">Case</span><span className="text-lg font-black text-amber-600">{stats.caseStudy}</span></div>
          <div className="flex flex-col items-center min-w-[32px]"><span className="text-[9px] font-black text-red-400 uppercase mb-1">Inact</span><span className="text-lg font-black text-red-500">{stats.inactive}</span></div>
        </div>

        <div className="relative flex-1 group w-full">
          <input type="text" placeholder="Search legal name or GSTIN..." value={search} onChange={e => setSearch(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-xl py-2.5 pl-10 pr-4 font-bold text-sm text-slate-900 focus:ring-2 focus:ring-indigo-600/10 outline-none" />
          <svg className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
