import React, { useState, useEffect, useMemo, useCallback } from 'react';
import ItMasterPortfolio from './ItMasterPortfolio';
import ITClientFormModal from '../Clientform/ITClientFormModal';
import { mockBackend } from '../../services/mockBackend';
import { Client, ClientStatus } from '../../types';

const CSV_HEADERS = [
  "Legal Name", "Trade Name", "Mobile", "Email", "Client Status",
  "PAN", "IT Category", "Portal Username", "Portal Password",
  "Bank Name", "Account No", "IFSC", "Remarks"
];

const ITPortfolio: React.FC = () => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [refreshTrigger, setRefreshTrigger] = useState(0);
  const [search, setSearch] = useState('');
  const [categoryFilter, setCategoryFilter] = useState<string>('All');
  const [showDataOptions, setShowDataOptions] = useState(false);
  const [clients, setClients] = useState<Client[]>([]);

  const refreshData = useCallback(async () => {
    const data = await mockBackend.getClients();
    setClients(data.filter(c => !!c.itProfile));
    setRefreshTrigger(p => p + 1);
  }, []);

  useEffect(() => {
    refreshData();
  }, []);

  const stats = useMemo(() => {
    const total = clients.length;
    const active = clients.filter(c => c.status === 'Active').length;
    const inactive = clients.filter(c => c.status === 'Inactive').length;
    return { total, active, inactive };
  }, [clients]);

  const categories = useMemo(() => {
    const cSet = new Set<string>();
    clients.forEach(c => { if (c.itProfile?.category) cSet.add(c.itProfile.category); });
    return Array.from(cSet).sort();
  }, [clients]);

  const handleExportCSV = () => {
    const rows = clients.map(c => [
      c.legalName, c.tradeName, c.mobile, c.email || "", c.status, c.itProfile?.pan || "",
      c.itProfile?.category || "", c.itProfile?.username || "", c.itProfile?.password || "",
      c.bankDetails?.bankName || "", c.bankDetails?.accountNo || "", c.bankDetails?.ifsc || "", `"${(c.remarks || "").replace(/"/g, '""')}"`
    ]);
    const csvContent = [CSV_HEADERS, ...rows].map(e => e.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `IT_Portfolio_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
    setShowDataOptions(false);
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async (e) => {
      const text = e.target?.result as string;
      const rows = text.split('\n').slice(1);
      const allClients = await mockBackend.getClients();
      for (const row of rows) {
        if (!row.trim()) continue;
        const cols = row.split(',').map(c => c.trim().replace(/^"|"$/g, ''));
        const pan = cols[5];
        if (!pan) continue;
        const existing = allClients.find(c => c.itProfile?.pan === pan);
        try {
          await mockBackend.saveClient({
            id: existing?.id, legalName: cols[0], tradeName: cols[1], mobile: cols[2], email: cols[3],
            status: (cols[4] as ClientStatus) || 'Active',
            itProfile: { pan, category: cols[6] || 'Individual', username: cols[7] || pan, password: cols[8] || '' },
            bankDetails: { bankName: cols[9] || '', accountNo: cols[10] || '', ifsc: cols[11] || '' },
            remarks: cols[12]
          });
        } catch (err) {}
      }
      refreshData();
      setShowDataOptions(false);
    };
    reader.readAsText(file);
    event.target.value = ''; 
  };

  return (
    <div className="flex flex-col h-full space-y-3 pb-4 overflow-hidden">
      <div className="flex flex-col lg:flex-row items-center gap-3 bg-white p-2.5 rounded-[1.5rem] border border-slate-200 shadow-sm shrink-0">
        <div className="flex items-center gap-4 px-2 border-r border-slate-100 hidden md:flex shrink-0">
          <div className="flex flex-col items-center min-w-[32px]"><span className="text-[9px] font-black text-slate-400 uppercase mb-1">Total</span><span className="text-lg font-black text-slate-900">{stats.total}</span></div>
          <div className="flex flex-col items-center min-w-[32px]"><span className="text-[9px] font-black text-emerald-500 uppercase mb-1">Active</span><span className="text-lg font-black text-emerald-600">{stats.active}</span></div>
          <div className="flex flex-col items-center min-w-[32px]"><span className="text-[9px] font-black text-red-500 uppercase mb-1">Inact</span><span className="text-lg font-black text-red-600">{stats.inactive}</span></div>
        </div>

        <div className="relative flex-1 group w-full">
          <input type="text" placeholder="Search PAN or legal name..." value={search} onChange={e => setSearch(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-xl py-2.5 pl-10 pr-4 font-bold text-sm text-slate-900 focus:ring-2 focus:ring-emerald-600/10 outline-none" />
          <svg className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        <div className="flex items-center gap-2 shrink-0">
          <select value={categoryFilter} onChange={e => setCategoryFilter(e.target.value)} className="bg-slate-50 border-none rounded-xl px-4 py-2.5 text-[11px] font-black uppercase text-slate-600 outline-none"><option value="All">Category: All</option>{categories.map(c => <option key={c} value={c}>{c}</option>)}</select>
        </div>

        <div className="flex items-center gap-2 shrink-0 ml-auto lg:ml-0">
          <div className="relative"><button onClick={() => setShowDataOptions(!showDataOptions)} className="h-10 w-10 flex items-center justify-center bg-slate-100 rounded-xl text-slate-600 hover:bg-emerald-600 hover:text-white transition-all"><svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 7v10c0 2 1 3 3 3h10c2 0 3-1 3-3V7c0-2-1-3-3-3H7C5 4 4 5 4 7zm4 4h8m-8 4h5" /></svg></button>
            {showDataOptions && (<div className="absolute right-0 mt-2 w-56 bg-white border border-slate-200 rounded-2xl shadow-2xl z-50 p-2 overflow-hidden"><button onClick={() => { const content = [CSV_HEADERS].join(","); const blob = new Blob([content], { type: 'text/csv' }); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = 'IT_Template.csv'; link.click(); }} className="w-full text-left px-4 py-3 text-[10px] font-black uppercase text-slate-600 hover:bg-slate-50 rounded-xl">Template</button><label className="w-full block px-4 py-3 text-[10px] font-black uppercase text-emerald-600 hover:bg-slate-50 rounded-xl cursor-pointer">Import <input type="file" accept=".csv" className="hidden" onChange={handleFileUpload} /></label><button onClick={handleExportCSV} className="w-full text-left px-4 py-3 text-[10px] font-black uppercase text-slate-600 hover:bg-slate-50 rounded-xl border-t">Export All</button></div>)}
          </div>
          <button onClick={() => setIsModalOpen(true)} className="bg-emerald-600 text-white font-black uppercase tracking-tight px-4 h-10 rounded-xl shadow-lg hover:bg-slate-900 transition-all flex items-center gap-2 text-sm"><svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg><span>Add Client</span></button>
        </div>
      </div>

      <div className="flex-1 min-h-0 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <ItMasterPortfolio key={refreshTrigger} externalSearch={search} hideInternalSearch={true} categoryFilter={categoryFilter} onDataChange={refreshData} />
      </div>
      <ITClientFormModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={refreshData} />
    </div>
  );
};

export default ITPortfolio;

import React, { useState, useEffect, useMemo } from 'react';
import { Client } from '../../types';
import { mockBackend } from '../../services/mockBackend';
import ITClientFormModal from '../Clientform/ITClientFormModal';
import Loader from '../../components/Loader';

interface ItMasterPortfolioProps {
  externalSearch?: string;
  hideInternalSearch?: boolean;
  categoryFilter?: string;
  onDataChange?: () => void;
}

const ItMasterPortfolio: React.FC<ItMasterPortfolioProps> = ({ 
  externalSearch = '', 
  hideInternalSearch = false,
  categoryFilter = 'All',
  onDataChange
}) => {
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [search, setSearch] = useState('');

  const [isItModalOpen, setIsItModalOpen] = useState(false);
  const [isDetailModalOpen, setIsDetailModalOpen] = useState(false);
  const [isLoginModalOpen, setIsLoginModalOpen] = useState(false);
  const [activeMenuId, setActiveMenuId] = useState<string | null>(null);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [statusColFilter, setStatusColFilter] = useState<string>('All');
  const [isStatusFilterOpen, setIsStatusFilterOpen] = useState(false);

  const [tempPassword, setTempPassword] = useState('');
  const [showPassInView, setShowPassInView] = useState(false);
  const [isEditingPassword, setIsEditingPassword] = useState(false);
  const [localPassValue, setLocalPassValue] = useState('');
  const [showPassInLogin, setShowPassInLogin] = useState(false);
  const [isSavingPass, setIsSavingPass] = useState(false);

  const fetchClients = async () => {
    setIsLoading(true);
    try {
      const data = await mockBackend.getClients();
      setClients(data.filter(c => !!c.itProfile) || []);
    } catch (error) {
      setClients([]);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => { fetchClients(); }, []);

  const filteredClients = useMemo(() => {
    let list = Array.isArray(clients) ? clients : [];
    if (categoryFilter !== 'All') list = list.filter(c => c.itProfile?.category === categoryFilter);
    if (statusColFilter !== 'All') list = list.filter(c => c.status === statusColFilter);
    const s = (externalSearch || search || '').toLowerCase();
    return list.filter(c => 
      (c.legalName || '').toLowerCase().includes(s) || 
      (c.tradeName || '').toLowerCase().includes(s) || 
      (c.itProfile?.pan && c.itProfile.pan.toLowerCase().includes(s)) || 
      (c.mobile || '').includes(s)
    );
  }, [clients, search, externalSearch, categoryFilter, statusColFilter]);

  const handleEdit = (client: Client) => { setSelectedClient(client); setIsItModalOpen(true); setIsDetailModalOpen(false); };

  const handleDelete = async (id: string) => { 
    if (confirm('Delete from vault?')) { 
      await mockBackend.deleteClient(id); 
      setIsDetailModalOpen(false); 
      onDataChange?.();
      fetchClients(); 
    } 
  };

  const copyToClipboard = (text: string) => navigator.clipboard.writeText(text);
  const shareViaWhatsApp = (text: string) => window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(text)}`, '_blank');

  const openPortalLogin = async (client: Client, finalPass?: string) => {
    if (finalPass && finalPass !== client.itProfile?.password) {
      await mockBackend.saveClient({ ...client, itProfile: { ...client.itProfile!, password: finalPass } });
      fetchClients();
    }
    copyToClipboard(client.itProfile?.username || '');
    window.open('https://eportal.incometax.gov.in/iec/foservices/#/login', '_blank');
  };

  const saveQuickPasswordFromView = async () => {
    if (!selectedClient) return;
    const updated = await mockBackend.saveClient({ ...selectedClient, itProfile: { ...selectedClient.itProfile!, password: localPassValue } });
    setSelectedClient(updated);
    setIsEditingPassword(false);
    onDataChange?.();
    fetchClients();
  };

  const handleModalSave = () => {
    fetchClients();
    onDataChange?.();
  };

  const getCredText = (c: Client) => `*IT Credentials*\n*PAN:* ${c.itProfile?.pan}\n*User:* ${c.itProfile?.username}\n*Pass:* ${c.itProfile?.password}`;

  if (isLoading) return <Loader />;

  return (
    <div className="flex flex-col h-full animate-in fade-in duration-500">
      <div className="flex-1 bg-white overflow-hidden flex flex-col">
        <div className="overflow-x-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse table-auto min-w-[1000px]">
            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-4 py-5 text-[14px] font-black uppercase text-slate-400 w-[60px]">S.No.</th>
                <th className="px-4 py-5 text-[14px] font-black uppercase text-slate-400">Name</th>
                <th className="px-4 py-5 text-[14px] font-black uppercase text-slate-400">Father Name</th>
                <th className="px-4 py-5 text-[14px] font-black uppercase text-slate-400">Trade/Company</th>
                <th className="px-4 py-5 text-[14px] font-black uppercase text-slate-400">Pan No.</th>
                <th className="px-4 py-5 text-[14px] font-black uppercase text-slate-400">Mobile No</th>
                <th className="px-4 py-5 text-center text-[14px] font-black uppercase text-slate-400">Status</th>
                <th className="px-4 py-5 text-[14px] font-black uppercase text-slate-400 text-right w-[100px]">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
