                <tr key={client.id} className={`group hover:bg-slate-50/50 ${idx % 2 === 0 ? 'bg-white' : 'bg-slate-50/30'}`}>
                  <td className="px-4 py-5 text-[12px] font-black text-slate-300">{(idx + 1).toString().padStart(2, '0')}</td>
                  <td className="px-4 py-5 text-[12px] font-black text-slate-900 uppercase truncate max-w-[180px]">{client.legalName}</td>
                  <td className="px-4 py-5 text-[12px] font-bold text-slate-500 uppercase truncate max-w-[160px]">{client.itProfile?.fatherName || '---'}</td>
                  <td className="px-4 py-5 text-[12px] font-black text-slate-700 truncate max-w-[160px] uppercase">{client.tradeName || client.itProfile?.companyName || '---'}</td>
                  <td className="px-4 py-5 whitespace-nowrap"><span className="text-[12px] font-black text-emerald-600 font-mono tracking-widest uppercase">{client.itProfile?.pan}</span></td>
                  <td className="px-4 py-5 whitespace-nowrap"><span className="text-[12px] font-black text-slate-600">{client.mobile || '---'}</span></td>
                  <td className="px-4 py-5 text-center"><span className={`px-2 py-0.5 rounded-full text-[9px] font-black uppercase ${client.status === 'Active' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>{client.status}</span></td>
                  <td className="px-4 py-5 text-right"><div className="relative inline-block text-left"><button onClick={() => setActiveMenuId(activeMenuId === client.id ? null : client.id)} className="h-8 w-8 rounded-lg bg-white border border-slate-200 text-slate-400 hover:text-slate-900 shadow-sm flex items-center justify-center transition-all"><svg className="h-4.5 w-4.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 5v.01M12 12v.01M12 19v.01" /></svg></button>{activeMenuId === client.id && (<><div className="fixed inset-0 z-40" onClick={() => setActiveMenuId(null)} /><div className="absolute right-0 mt-2 w-56 bg-white border border-slate-200 rounded-2xl shadow-2xl z-50 p-1.5 animate-in zoom-in-95 overflow-hidden"><button onClick={() => { setSelectedClient(client); setTempPassword(client.itProfile?.password || ''); setIsLoginModalOpen(true); setActiveMenuId(null); }} className="w-full flex items-center gap-3 px-3 py-2.5 text-[10px] font-black uppercase tracking-widest text-slate-600 hover:bg-emerald-50 hover:text-emerald-600 rounded-xl"><svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 16l-4-4m0 0l4-4" /></svg>Login Gateway</button><button onClick={() => { setSelectedClient(client); setIsDetailModalOpen(true); setActiveMenuId(null); }} className="w-full flex items-center gap-3 px-3 py-2.5 text-[10px] font-black uppercase tracking-widest text-slate-600 hover:bg-indigo-50 hover:text-indigo-600 rounded-xl"><svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>View Detail</button><button onClick={() => { shareViaWhatsApp(getCredText(client)); setActiveMenuId(null); }} className="w-full flex items-center gap-3 px-3 py-2.5 text-[10px] font-black upper